// Source fallback for dev/static serving. Production dist/sw.js is generated by vite.config.ts
// with a baked BUILD_ID and exact hashed JS/CSS critical asset list.
const BUILD_ID = 'dev-source-fallback';
const SHELL = `wordgame-shell-${BUILD_ID}`;
const RUNTIME = 'wordgame-runtime';
const BASE_PATH = new URL(self.registration.scope).pathname;
const INDEX_PATH = `${BASE_PATH}index.html`;
const CRITICAL = [BASE_PATH, INDEX_PATH, `${BASE_PATH}manifest.webmanifest`, `${BASE_PATH}icons/icon-192.svg`, `${BASE_PATH}icons/icon-512.svg`];
const READY_TIMEOUT_MS = 2500;

self.addEventListener('install', event => {
  event.waitUntil((async () => {
    const cache = await caches.open(SHELL);
    await cache.addAll(CRITICAL);
  })());
});
self.addEventListener('activate', event => { event.waitUntil(self.clients.claim()); });

async function clientReady(client) {
  return await new Promise(resolve => {
    const channel = new MessageChannel();
    const timer = setTimeout(() => resolve(false), READY_TIMEOUT_MS);
    channel.port1.onmessage = event => { clearTimeout(timer); resolve(event.data?.type === 'WC_READY_RESPONSE' && event.data.ready === true); };
    try { client.postMessage({ type: 'WC_READY_REQUEST', buildId: BUILD_ID }, [channel.port2]); } catch { clearTimeout(timer); resolve(false); }
  });
}
async function allWindowClientsReady() {
  const clients = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
  const results = await Promise.all(clients.map(clientReady));
  return results.length > 0 && results.every(Boolean);
}

self.addEventListener('message', event => {
  if (event.data?.type === 'SKIP_WAITING_IF_SAFE' && event.data.safe === true && event.data.owner) event.waitUntil((async () => { if (await allWindowClientsReady()) await self.skipWaiting(); })());
  if (event.data?.type === 'BOOT_OK' && event.data.buildId === BUILD_ID) event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter(k => k.startsWith('wordgame-shell-') && k !== SHELL).map(k => caches.delete(k)));
  })());
});

async function boundedPut(cache, request, response) {
  await cache.put(request, response);
  const keys = await cache.keys();
  while (keys.length > 60) { const key = keys.shift(); if (key) await cache.delete(key); }
}
function criticalRequestFor(request, url) { if (!url.pathname.startsWith(BASE_PATH)) return undefined; return request.mode === 'navigate' ? INDEX_PATH : (CRITICAL.includes(url.pathname) ? url.pathname : undefined); }
self.addEventListener('fetch', event => {
  const url = new URL(event.request.url);
  if (url.origin !== self.location.origin || event.request.method !== 'GET') return;
  event.respondWith((async () => {
    const shellKey = criticalRequestFor(event.request, url);
    const shellCache = await caches.open(SHELL);
    if (shellKey) {
      const cached = await shellCache.match(shellKey);
      if (cached) return cached;
      const response = await fetch(event.request);
      if (response.ok && response.type === 'basic') await shellCache.put(shellKey, response.clone());
      return response;
    }
    const runtimeCache = await caches.open(RUNTIME);
    const cached = await runtimeCache.match(event.request);
    if (cached) return cached;
    try { const response = await fetch(event.request); if (response.ok && response.type === 'basic') await boundedPut(runtimeCache, event.request, response.clone()); return response; }
    catch { return event.request.mode === 'navigate' ? (await shellCache.match(INDEX_PATH)) || Response.error() : Response.error(); }
  })());
});
